/**
 * Hand-made corrections applied on top of the baked OSM data in
 * saddarData.ts (which is regenerated by tools/osm2saddar.py and so should
 * not be edited by hand). Pure data transforms: deterministic, no I/O.
 */

type NodeRow = readonly [number, number, 0 | 1];
type LinkRow = readonly [number, number, 0 | 1 | 2, number, number, 0 | 1, 0 | 1, string];
type SegRow = readonly [number, number, number];
type IslandRow = readonly [number, number, number, 0 | 1];

export interface RoadData {
  nodes: NodeRow[];
  links: LinkRow[];
  segs: SegRow[];
  islands: IslandRow[];
}

export interface RoundaboutSpec {
  name: string;
  /** centre (sim x, z) */
  x: number;
  z: number;
  /** ring centreline radius (m) */
  r: number;
  /** central island radius (m) */
  island: number;
  /** ring nodes */
  k: number;
  lanes: number;
  laneW: number;
  /** junction nodes the ring replaces; every link/seg touching them is rerouted */
  replace: readonly number[];
}

/**
 * Merewether Tower Chowk: M.A. Jinnah Road (a divided road), Preedy Street
 * and Grieg Street meet at nodes 214/67, and the 1892 tower stands in the
 * middle of the junction as a roundabout island. OSM has it as a plain
 * crossing beside the tower, so we build the ring here.
 */
export const MEREWETHER_CHOWK: RoundaboutSpec = {
  name: 'Merewether Tower Chowk',
  x: -902.0,
  z: 262.0,
  r: 15.0,
  island: 9.5,
  k: 24,
  lanes: 2,
  laneW: 3.1,
  replace: [214, 67],
};

/** Outer asphalt radius of a patched roundabout. */
export function ringOuterR(s: RoundaboutSpec): number {
  return s.r + (s.lanes * s.laneW) / 2;
}

/**
 * Replaces the junction nodes in `s.replace` with a one-way ring of `s.k`
 * nodes circulating clockwise seen from above (left-hand traffic, like
 * Fawara Chowk). Each approach link/seg is reattached to the ring node
 * nearest its bearing; links between the replaced nodes are dropped. The
 * replaced nodes stay in the array (indices are stable) with no links.
 */
export function addRoundabout(d: RoadData, s: RoundaboutSpec): void {
  const base = d.nodes.length;
  for (let i = 0; i < s.k; i++) {
    // Node i at angle -i·step: increasing index runs clockwise.
    const a = -(i / s.k) * Math.PI * 2;
    d.nodes.push([s.x + Math.cos(a) * s.r, s.z + Math.sin(a) * s.r, 1]);
  }
  const replaced = new Set(s.replace);
  const nearestRing = (other: number) => {
    const [ox, oz] = d.nodes[other];
    let a = Math.atan2(oz - s.z, ox - s.x);
    if (a > 0) a -= Math.PI * 2; // ring angles run 0 .. -2π
    const i = Math.round((-a / (Math.PI * 2)) * s.k) % s.k;
    return base + i;
  };
  const links: LinkRow[] = [];
  for (const l of d.links) {
    const [u, v] = l;
    const ru = replaced.has(u), rv = replaced.has(v);
    if (ru && rv) continue;
    if (ru) links.push([nearestRing(v), v, l[2], l[3], l[4], l[5], l[6], l[7]]);
    else if (rv) links.push([u, nearestRing(u), l[2], l[3], l[4], l[5], l[6], l[7]]);
    else links.push(l);
  }
  for (let i = 0; i < s.k; i++) links.push([base + i, base + ((i + 1) % s.k), 0, s.lanes, s.laneW, 1, 0, s.name]);
  d.links = links;

  const segs: SegRow[] = [];
  for (const g of d.segs) {
    const [u, v, hw] = g;
    const ru = replaced.has(u), rv = replaced.has(v);
    if (ru && rv) continue;
    if (ru) segs.push([nearestRing(v), v, hw]);
    else if (rv) segs.push([u, nearestRing(u), hw]);
    else segs.push(g);
  }
  for (let i = 0; i < s.k; i++) segs.push([base + i, base + ((i + 1) % s.k), (s.lanes * s.laneW) / 2]);
  d.segs = segs;

  d.islands.push([s.x, s.z, s.island, 0]);
}

/** Every roundabout this file adds (renderers clip baked pavements against them). */
export const PATCHED_ROUNDABOUTS: readonly RoundaboutSpec[] = [MEREWETHER_CHOWK];

export function applyRoadPatches(d: RoadData): void {
  for (const s of PATCHED_ROUNDABOUTS) addRoundabout(d, s);
}
